import crypto from 'node:crypto'
import fs from 'node:fs'
import path from 'node:path'
import {pathToFileURL} from 'node:url'

const [cppRoot,cpuRoot,ledger]=process.argv.slice(2)
if (![cppRoot,cpuRoot,ledger].every(value=>value&&path.isAbsolute(value))) throw Error('pass absolute repository, CPU root, and ledger paths')
const authority=await import(pathToFileURL(path.join(cppRoot,'tools/dsl/corpus_authority.mjs')).href)
authority.authenticateCpuRoot(cpuRoot,ledger)
const load=p=>import(pathToFileURL(path.join(cpuRoot,p)).href)
const [{canonicalKernelFactories,canonicalAdapterFactories,kernelFactories},{bindCanonicalKernel},{runPass},{Surface},{UPSTREAM_REVISION}]=await Promise.all([
 load('src/effects/catalog.js'),load('src/csl/glsl-kernel.js'),load('src/runtime/pass-runner.js'),
 load('src/runtime/surface.js'),load('src/effects/generated/upstream-snapshot.js')])
if(process.version!=='v26.0.0'||UPSTREAM_REVISION!=='6cb1a3c3e21010db956d41e7a6d57a02b0be1e7d')throw Error('CPU runtime/source revision mismatch')
const sha=b=>crypto.createHash('sha256').update(b).digest('hex')
const bytes=x=>Buffer.from(x.buffer,x.byteOffset,x.byteLength)
const words=x=>Array.from(new Uint32Array(x.buffer,x.byteOffset,x.byteLength/4),w=>`0x${(w>>>0).toString(16).padStart(8,'0')}`)
const f=Math.fround
const corpus='6cb1a3c3e21010db956d41e7a6d57a02b0be1e7d'
const metadata=JSON.parse(fs.readFileSync(path.join(cppRoot,'tools/glslcpp/corpus',corpus,'metadata.json')))
const original={
 noise:JSON.parse(fs.readFileSync(path.join(cppRoot,'docs/port-engineering/classic-noise-parity/classic-noise-oracles.json'))),
 moodscape:JSON.parse(fs.readFileSync(path.join(cppRoot,'docs/port-engineering/moodscape-parity/moodscape-oracles.json'))),
}
const contracts={
 noise:{key:'classicNoisedeck/noise:noise',effect:'classicNoisedeck/noise',factory:'canonicalFactory12',factoryHash:'1a082f9e24533bf5e7f0e4cdb61469fb8a3c01c580c468f4760a3d9463b095a2',base:'negative-speed-offset',alt:'max-ridges'},
 moodscape:{key:'classicNoisedeck/moodscape:moodscape',effect:'classicNoisedeck/moodscape',factory:'canonicalFactory11',factoryHash:'b5fe9e225f841e285dace48441ae3945b035b269e2a2e7e4d4938a3357d60fc6',base:'tile-offset',alt:'negative-intensity'},
}
const defaultDefines={noise:{COLOR_MODE:6,LOOP_OFFSET:300,METRIC:0,NOISE_TYPE:10,REFRACT_MODE:2},moodscape:{COLOR_MODE:2,NOISE_TYPE:10}}
function sourceFactory(label){const c=contracts[label],v=canonicalKernelFactories[c.key];if(typeof v!=='function'||v.name!==c.factory||sha(v.toString())!==c.factoryHash||kernelFactories.get(c.key)!==v||canonicalAdapterFactories[c.key]!==undefined)throw Error(`${label}: CPU canonical factory identity drift`);return v}
function defineDomains(label){const result={};for(const [name,param] of Object.entries(metadata.effects[contracts[label].effect].params)){if(!param.define)continue;const values=[...new Set(Object.values(param.choices??{}).filter(Number.isInteger))].sort((a,b)=>a-b);if(!values.includes(param.default))throw Error(`${label}:${name}: default missing from declared choices`);if(result[param.define])throw Error(`${label}: duplicate define`);result[param.define]={param:name,default:param.default,values}}if(Object.keys(result).sort().join()!=Object.keys(defaultDefines[label]).sort().join())throw Error(`${label}: define census mismatch`);return result}
function inputs(label){const c=contracts[label];const cases=original[label].render_cases;const get=n=>cases.find(x=>x.name===n);const base=get(c.base),alt=get(c.alt);if(!base||!alt)throw Error(`${label}: frozen parameter case missing`);return{base,alt}}
const snapshotValue=v=>v instanceof Float32Array?{kind:'Float32Array',words:words(v),bytes:[...bytes(v)]}:Array.isArray(v)?v.map(snapshotValue):v&&typeof v==='object'?Object.fromEntries(Object.entries(v).sort(([a],[b])=>a.localeCompare(b)).map(([k,x])=>[k,snapshotValue(x)])):v
function bindings(label,spec,defines){const resolution=new Float32Array(label==='noise'?spec.resolution.map(f):[spec.width,spec.height]);const tileOffset=new Float32Array(spec.tileOffset.map(f));const fullResolution=new Float32Array(spec.fullResolution.map(f));if(label==='moodscape')return {NOISE_TYPE:defines.NOISE_TYPE,COLOR_MODE:defines.COLOR_MODE,time:f(spec.time),seed:spec.seed,wrap:spec.wrap,resolution,tileOffset,fullResolution,noiseScale:f(spec.noiseScale),refractAmt:f(spec.refractAmt),speed:f(spec.speed),hueRotation:f(spec.hueRotation),hueRange:f(spec.hueRange),intensity:f(spec.intensity),ridges:spec.ridges};return{NOISE_TYPE:defines.NOISE_TYPE,REFRACT_MODE:defines.REFRACT_MODE,LOOP_OFFSET:defines.LOOP_OFFSET,METRIC:defines.METRIC,COLOR_MODE:defines.COLOR_MODE,time:f(spec.time),seed:spec.seed,resolution,tileOffset,fullResolution,xScale:f(spec.xScale),yScale:f(spec.yScale),octaves:spec.octaves,ridges:spec.ridges,refractAmt:f(spec.refractAmt),kaleido:f(spec.kaleido),loopScale:f(spec.loopScale),speed:f(spec.speed),paletteMode:spec.paletteMode,paletteOffset:new Float32Array(spec.paletteOffset.map(f)),paletteAmp:new Float32Array(spec.paletteAmp.map(f)),paletteFreq:new Float32Array(spec.paletteFreq.map(f)),palettePhase:new Float32Array(spec.palettePhase.map(f)),cyclePalette:spec.cyclePalette,rotatePalette:f(spec.rotatePalette),repeatPalette:f(spec.repeatPalette),hueRange:f(spec.hueRange),hueRotation:f(spec.hueRotation),wrap:spec.wrap}}
function render(label,spec,defines){const c=contracts[label],b=bindings(label,spec,defines),options={width:spec.width,height:spec.height,time:b.time,seed:b.seed,wrap:b.wrap,resolution:b.resolution,tileOffset:b.tileOffset,fullResolution:b.fullResolution,uniforms:b},before=JSON.stringify(snapshotValue({bindings:b,options}));const surface=new Surface(spec.width,spec.height),kernel=bindCanonicalKernel(sourceFactory(label),options);runPass({kernel,destination:surface,tileRows:2});if(before!==JSON.stringify(snapshotValue({bindings:b,options})))throw Error(`${label}: CPU input mutation`);const rgba=surface.toRgba8();if(surface.data.length!==spec.width*spec.height*4||rgba.length!==surface.data.length)throw Error(`${label}: output extent mismatch`);return {surface,f32_sha256:sha(bytes(surface.data)),rgba8_sha256:sha(Buffer.from(rgba)),f32_words_le:words(surface.data),rgba8_bytes:[...rgba]}}
function cases(label,domains){const {base,alt}=inputs(label),out=[];out.push({name:'base-default',parameters:base,defines:{...defaultDefines[label]},dimension:'baseline'});for(const [define,domain] of Object.entries(domains)){for(const value of domain.values)out.push({name:`${define}-${value}`,parameters:base,defines:{...defaultDefines[label],[define]:value},dimension:define})}if(label==='noise'){
 out.push({name:'cross-constant-oklab',parameters:alt,defines:{...defaultDefines[label],NOISE_TYPE:0,COLOR_MODE:3},dimension:'cross'});
 out.push({name:'cross-spline-palette',parameters:alt,defines:{...defaultDefines[label],NOISE_TYPE:6,COLOR_MODE:4,REFRACT_MODE:1},dimension:'cross'});
 out.push({name:'cross-hash-metric',parameters:alt,defines:{...defaultDefines[label],NOISE_TYPE:11,COLOR_MODE:2,LOOP_OFFSET:120,METRIC:5,REFRACT_MODE:0},dimension:'cross'});
}else{
 out.push({name:'cross-constant-oklab',parameters:alt,defines:{...defaultDefines[label],NOISE_TYPE:0,COLOR_MODE:3},dimension:'cross'});
 out.push({name:'cross-spline-mono',parameters:alt,defines:{...defaultDefines[label],NOISE_TYPE:6,COLOR_MODE:0},dimension:'cross'});
 out.push({name:'cross-linear-rgb',parameters:alt,defines:{...defaultDefines[label],NOISE_TYPE:1,COLOR_MODE:1},dimension:'cross'});
}return out}
const effects=[]
for(const label of ['noise','moodscape']){const c=contracts[label],domains=defineDomains(label),rows=[];for(const spec of cases(label,domains)){const first=render(label,spec.parameters,spec.defines),second=render(label,spec.parameters,spec.defines);if(first.surface===second.surface||first.surface.data.buffer===second.surface.data.buffer||first.f32_sha256!==second.f32_sha256||first.rgba8_sha256!==second.rgba8_sha256||JSON.stringify(first.f32_words_le)!==JSON.stringify(second.f32_words_le)||JSON.stringify(first.rgba8_bytes)!==JSON.stringify(second.rgba8_bytes))throw Error(`${label}:${spec.name}: repeat/storage mismatch`);const p=spec.parameters;const fields=label==='noise'?['width','height','time','seed','resolution','tileOffset','fullResolution','xScale','yScale','octaves','ridges','refractAmt','kaleido','loopScale','speed','paletteMode','paletteOffset','paletteAmp','paletteFreq','palettePhase','cyclePalette','rotatePalette','repeatPalette','hueRange','hueRotation','wrap']:['width','height','time','seed','tileOffset','fullResolution','noiseScale','refractAmt','speed','hueRotation','hueRange','intensity','ridges','wrap'];rows.push({name:spec.name,dimension:spec.dimension,defines:spec.defines,parameters:Object.fromEntries(fields.map(k=>[k,p[k]])),expected:{f32_sha256:first.f32_sha256,rgba8_sha256:first.rgba8_sha256,f32_words_le:first.f32_words_le,rgba8_bytes:first.rgba8_bytes},repeat_exact:true,distinct_storage:true,inputs_unchanged:true})}for(const [def,domain] of Object.entries(domains)){const observed=rows.filter(x=>x.dimension===def).map(x=>x.defines[def]).sort((a,b)=>a-b);if(JSON.stringify(observed)!==JSON.stringify(domain.values))throw Error(`${label}:${def}: enum value missing`)}effects.push({label,program_key:c.key,factory_name:c.factory,factory_text_sha256:c.factoryHash,define_domains:domains,cases:rows})}
const result={schema:'noisemaker-for-cpp.classic-moodscape.dynamic-cpu-oracle.v1',cpu_root_revision:'9f3bd6a',upstream_revision:UPSTREAM_REVISION,node_version:process.version,authority_ledger_sha256:sha(fs.readFileSync(ledger)),source_corpus_revision:corpus,exactness:'all raw Float32 words and RGBA8 bytes; no tolerance',effects}
process.stdout.write(JSON.stringify(result,null,2)+'\n')
